INSERT INTO public.page_blocks(id,landing_page_id,block_type,title,subtitle,content,image_url,button_text,button_link,background_color,text_color,order_index,is_visible,settings,created_at,updated_at,font_size,title_color,title_font_size,subtitle_color,subtitle_font_size,content_color,content_font_size) VALUES
('c96d660e-1676-452f-becf-8a52dda4409c','0f1171e5-4dcd-403c-9b99-c39cc0434622','hero','Participe de uma Reunião Gratuita e Descubra o Poder do Networking Estruturado','Conheça outros empresários e profissionais que estão, como você, comprometidos ao crescimento e relacionamento qualificado.','Faça conexões estratégicas com empresários e profissionais que compartilham seus objetivos de crescimento.',NULL,'Participe Gratuitamente','#form','#E85D1C','#FFFFFF',1,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-15T14:45:21.24886+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('8a99d8cd-e36e-44cf-bcc8-81addde231ec','0f1171e5-4dcd-403c-9b99-c39cc0434622','info','Como Vamos Ajudar Seu Negócio','No Gente, oferecemos um programa estruturado de networking que gera resultados reais para suas empresas','🤝 **Contatos** - Acesse uma rede de empresários em diversos segmentos, criando oportunidades de negócios com parcerias estratégicas.

📈 **Relacionamentos** - Mantenha-se atualizado com as mais recentes práticas, estratégias e tendências do seu mercado.

🎯 **Parcerias** - Tenha acesso a um grupo comprometido com oportunidades e desenvolvimento, sempre visando o crescimento.

🚀 **Resultado** - Resultados comprovados do nosso grupo e de muitos profissionais de sucesso.','https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1768490884426-95h2xpcak49.jpg',NULL,NULL,'#FFFFFF','#1E3A5F',2,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-15T15:29:03.935574+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('2ca7a6eb-a1b2-49c9-b54c-d8e2b0b9974c','0f1171e5-4dcd-403c-9b99-c39cc0434622','info','Nossas Dinâmicas','No Gente, organizamos encontros que vão além de simples troca de cartões de visita: criamos experiências que promovem conexões','⏱️ **Meu Cliente em 1 Minuto** - Aprenda e desenvolva uma técnica de apresentação rápida do seu negócio, produto e serviço. Cause impacto e interesse dos demais membros do grupo, abrindo as portas para para construir novos relacionamentos.

💼 **Negócio em Foco** - Um espaço de 20 minutos para você apresentar sua empresa com maiores detalhes, educando os demais membros sobre seus produtos e serviços, facilitando a indicação de novos clientes e a formação de parcerias de negócios.

🏛️ **Conselho de Administração** - Compartilhe com os demais membros do grupo os desafios que você enfrenta na sua empresa e conte com o aconselhamento de pessoas experientes e bem sucedidas para superá-los.

💧 **Gente em Ação** - As Reuniões 1 a 1 permitem que nossos membros aprofundem o conhecimento de seus negócios, e encontrem maneiras de colaborar e crescer juntos, em um ambiente menos formal e mais pessoal, que favorece a construção de relacionamentos mais fortes e duradouros.',NULL,'Quero estar no próximo encontro!','#form','#F5F5F5','#1E3A5F',3,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-15T16:08:14.652064+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('7d59ca73-d3ac-44e9-aa6b-b22109d917fc','0f1171e5-4dcd-403c-9b99-c39cc0434622','cta','Vagas Limitadas para Visitantes','Para garantir a qualidade de nossos encontros, limitamos a participação de visitantes. Solicite agora mesmo sua participação e não perca a oportunidade de fazer networking no GeNtE!',NULL,'https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1768490858420-puci8hvuux.jpg','Garantir Minha Vaga no Encontro','#form','#E85D1C','#FFFFFF',4,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-15T16:10:08.885193+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('5ac805a6-37be-4464-8549-a7bd697db4de','0f1171e5-4dcd-403c-9b99-c39cc0434622','testimonials','O Que Nossos Membros Dizem','Veja o que falam sobre a experiência no Gente Networking','[{"name": "Aline de Souza", "role": "Empresária", "text": "O Gente proporcionou parcerias extraordinárias, como se a empresa tivesse vários diretores! Finalmente posso me sentir apoiada em decisões importantes."}, {"name": "Carlos Gonçalves", "role": "Diretor Comercial", "text": "Depois que entrei no Gente, minhas vendas aumentaram muito. Hoje minha maior rede de parcerias e networking vem daí. O grupo é muito forte."}, {"name": "Ivar Müller", "role": "Consultor Empresarial", "text": "O GENTE é um dos grupos de NETWORKING que participo. Nele eu aprendo técnicas, desenvolvo e multiplico meus ganhos em negócios."}]',NULL,NULL,NULL,'#1E3A5F','#FFFFFF',5,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-15T15:29:31.439803+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('c3720c2a-04ad-4cba-839a-1772282d364e','0f1171e5-4dcd-403c-9b99-c39cc0434622','form','Participe e Gere Negócios!','Preencha o formulário abaixo e participe gratuitamente do nosso próximo encontro quinzenal!',NULL,NULL,NULL,NULL,'#FFFFFF','#1E3A5F',6,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-13T22:12:35.980606+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('5132881f-b159-4b46-9be8-50d3f1f91236','0f1171e5-4dcd-403c-9b99-c39cc0434622','faq','Perguntas Frequentes',NULL,'[{"question": "Como são os encontros do Gente?", "answer": "Nossos encontros são quinzenais e online, com dinâmicas estruturadas de networking, apresentações de negócios e troca de experiências entre empreendedores."}, {"question": "A participação como visitante é gratuita?", "answer": "Sim! Sua primeira participação é totalmente gratuita. Queremos que você experimente e sinta o valor do nosso grupo antes de qualquer compromisso."}, {"question": "Qual o investimento para se tornar membro?", "answer": "Após a primeira visita, você poderá avaliar o plano de associação que melhor se adapta às suas necessidades. Entre em contato para saber mais sobre nossos planos."}, {"question": "Quem pode participar do Gente?", "answer": "Empresários, empreendedores e profissionais liberais que buscam ampliar sua rede de contatos e gerar novos negócios através de networking estruturado."}]',NULL,NULL,NULL,'#F5F5F5','#1E3A5F',7,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-13T22:12:35.980606+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('97ba395b-dbdc-4949-9ee5-bcaa2dc26a55','0f1171e5-4dcd-403c-9b99-c39cc0434622','info','O Facilitador do Processo','Desde 2011 no Brasil, Gente Networking','**Eduardo Mendonça**

Com 20 anos de experiência executiva na Coca-Cola, atua desde 2013 como Mentor Empresarial e desde 2019 facilita o GeNtE Grupo de Networking Empresarial.


_"O networking de negócios é uma atividade com alto retorno de investimento se feito da forma correta. No GeNtE procuramos estimular a construção de relacionamentos e formação de parcerias estratégicas. As indicações de negócios são uma consequência natural."_

— Eduardo Mendonça, Fundador do Gente Networking','https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1768354969506-r2vgmyd7ghr.jpg',NULL,NULL,'#FFFFFF','#1E3A5F',8,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-15T16:11:50.57649+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('d3195a35-0f66-43a1-bdf5-8801032486a6','0f1171e5-4dcd-403c-9b99-c39cc0434622','cta','Pronto para Expandir Seus Negócios?','Participe de uma reunião gratuita e veja como o networking estruturado pode transformar seus resultados',NULL,'https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1768490858420-puci8hvuux.jpg','Participar Agora','#form','#1E3A5F','#FFFFFF',9,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-15T16:12:11.831023+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('3dc7c4ec-475e-4a80-8275-6db51bd788d8','13ddfd31-718d-4cd8-ad38-8c84d68fe051','hero','21º GENTE HUB','Participe de um evento inovador, com uma proposta de valor única! Desenvolva sua rede de contatos e assista uma palestra inspiradora!','Um evento único que combina networking estratégico com uma palestra transformadora.','https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1768355357092-ovfoaqjrdr.png','Reservar Minha Vaga','#form','#E85D1C','#FFFFFF',1,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-10-09T11:57:34.617449+00:00','2.4rem',NULL,'3rem',NULL,NULL,NULL,NULL),
('403678d5-8061-4cb0-87e4-dce21f37cf70','13ddfd31-718d-4cd8-ad38-8c84d68fe051','info','Networking É Conexão','No Gente Hub você tem acesso a uma comunidade de empreendedores de alto impacto, a oportunidades de negócios e aprendizado de qualidade.','💼 **Salas de Conexão** - São várias rodadas curtas de negócios onde você troca experiências e gera novas oportunidades.

🤝 **Conexões** - Amplie seu círculo de contatos conhecendo empresários e profissionais de diversos segmentos e mercados.

📚 **Aprendizado** - Conteúdo exclusivo sobre temas relevantes para seu negócio avançar no mercado.','https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1787057664087-32say9nstk2.jpg','Inscreva-se Agora!','#form','#1E3A5F','#FFFFFF',2,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-08-18T12:54:41.441598+00:00',NULL,NULL,NULL,'#ffffff',NULL,NULL,NULL),
('81a70b6f-6fdf-4dd5-8ba6-24ad60063d48','13ddfd31-718d-4cd8-ad38-8c84d68fe051','countdown','Vagas Limitadas','Garanta seu lugar no próximo Gente Hub','Falta pouco para o evento! Vai ficar de fora? Garanta a sua vaga agora mesmo!',NULL,'Reserve sua Vaga!','#form','#1E3A5F','#FFFFFF',3,true,'{"target_date": "2025-01-30T19:00:00-03:00"}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-14T18:53:09.475643+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('74ce1c57-5fb2-4986-b2f7-2d1f5a7963a3','13ddfd31-718d-4cd8-ad38-8c84d68fe051','info','Agenda do Gente Hub','Uma noite de muita conexão, troca de experiências e conteúdo','⏰ **19:00** - Recepção e Abertura da Sala
Recepção dos participantes e início do networking informal.

🤝 **19:10** - 1ª Rodada de Networking nas Salas de Conexão
Apresentações estruturadas entre os participantes do evento para maximizar as conexões.

🎤 **19:25** - Palestra com Dr. Vitor Oliveira
7 Erros Silenciosos Que Fazem Empresas Perderem Dinheiro Sem Perceber.

💼 **19:45** - Perguntas e Respostas
Espaço para esclarecimentos sobre o tema da palesta.

🤝 **20:00** - 2ª Rodada de Networking nas Salas de Conexão
Aprofundamento nas conexões e geração de novas oportunidades para todos.

💯 **20:15** - Encerramento
Agora é aplicar o conhecimento adquirido e aproveitar as conexões realizadas!','https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1768355357092-ovfoaqjrdr.png',NULL,NULL,'#F5F5F5','#1E3A5F',4,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-05-18T22:17:57.967028+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('6f282427-5e75-4a49-8325-e11805041eea','13ddfd31-718d-4cd8-ad38-8c84d68fe051','info','Ruído na comunicação pode acabar com a sua empresa!',NULL,'Nesta edição trazemos um tema especial (e pouco discutido) para que possamos alinhar a comunicação em nossas empresas: **Ruído na comunicação pode acabar com a sua empresa!**.

O especialista em marketing e comunicação Flavio Paiva irá mostrar, de forma clara e prática, como uma mensagem mal passada pode gerar grandes transtornos em sua organização.

✅ Identifique como falhas de comunicação podem gerar conflitos, retrabalho e prejuízos para sua empresa.
✅ Aprenda a transmitir mensagens com mais clareza, evitando interpretações equivocadas e desalinhamentos na equipe.
✅ Descubra como melhorar a comunicação interna e fortalecer o relacionamento com clientes, parceiros e colaboradores.','https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1791548177593-nurh0rlolv.jpeg','Não perca essa oportunidade!','#form','#FFFFFF','#1E3A5F',5,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-10-09T22:18:20.632351+00:00',NULL,NULL,NULL,NULL,'1.5rem',NULL,NULL),
('9c5ab320-d84c-4c8d-80c4-18f710c9e2a8','13ddfd31-718d-4cd8-ad38-8c84d68fe051','testimonials','Quem Participou, Recomenda','Veja o que dizem sobre o Gente Hub','[{"name": "Maria Carolina Alves", "role": "Empresária", "text": "Participar do Gente Hub foi transformador para meu negócio! As conexões que fiz geraram parcerias que aumentaram meu faturamento em 40%."}, {"name": "João Marcos Almeida", "role": "Consultor", "text": "O Gente Networking é uma porta de entrada para um networking qualificado! Participando do Gente Hub, já fechei 3 contratos importantes."}, {"name": "José Cardoso Viana", "role": "Diretor Comercial", "text": "Uma oportunidade única de conhecer empreendedores de alto nível. Cada evento do Gente Hub traz insights valiosos para os negócios."}]',NULL,NULL,NULL,'#FFFFFF','#1E3A5F',6,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-13T22:12:35.980606+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('e7e4be38-272f-4c25-bab5-9715197426d8','13ddfd31-718d-4cd8-ad38-8c84d68fe051','form','Garanta Seu Lugar!','Preencha o formulário abaixo para participar do próximo Gente Hub',NULL,NULL,NULL,NULL,'#F5F5F5','#1E3A5F',7,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-13T22:12:35.980606+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('2ddc5b66-a604-448c-9505-4317e7863635','13ddfd31-718d-4cd8-ad38-8c84d68fe051','faq','Perguntas Frequentes',NULL,'[{"question": "O que é o Gente Hub?", "answer": "É um evento online focado em networking e aprendizado, voltado para empreendedores, profissionais liberais, prestadores de serviços, assessores e consultores."}, {"question": "Qual o formato do evento?", "answer": "Início com recepção - Participação em 2 Salas de Conexão para networking com outros profissionais - Palestra no estilo TEDex com um(a) especialista - Sessão de Perguntas e Respostas - Segunda rodada de networking - Encerramento"}, {"question": "Quanto custa para participar?", "answer": "A participação como visitante é gratuita! Queremos que você experimente o valor do evento antes de qualquer compromisso."}, {"question": "Tenho que ser empresário?", "answer": "O Gente Hub é aberto para empresários, empreendedores e profissionais liberais que buscam ampliar sua rede de contatos e gerar novos negócios."}, {"question": "Quem pode participar?", "answer": "O GeNtE HUB é destinado a: Empreendedores, Profissionais liberais, Prestadores de serviços, Assessores e consultores"}, {"question": "Há limite de vagas?", "answer": "Sim, as vagas são limitadas. O site enfatiza que restam poucos lugares, com contagem regressiva para o evento."}]',NULL,NULL,NULL,'#FFFFFF','#1E3A5F',8,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-14T17:52:31.909876+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('8590f6a1-b6a5-4768-9db2-1fe2c43bafa5','13ddfd31-718d-4cd8-ad38-8c84d68fe051','cta','Venha Participar do Gente Hub e Faça Conexões de Valor para Seu Negócio!','Não perca a oportunidade de participar deste evento de networking e expandir suas conexões de negócios.',NULL,'https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1768355403828-sp46nmwuxxn.png','Garantir Minha Vaga','#form','#E85D1C','#FFFFFF',9,true,'{}'::jsonb,'2026-01-13T22:12:35.980606+00:00','2026-01-14T17:50:58.728018+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL);